mkfn!{
    join_introspect!();
    #[doc = " Takes two closures and *potentially* runs them in parallel. It"] #[doc = " returns a pair of the results from those closures."] #[doc = ""] #[doc = " Conceptually, calling `join()` is similar to spawning two threads,"] #[doc = " one executing each of the two closures. However, the"] #[doc = " implementation is quite different and incurs very low"] #[doc = " overhead. The underlying technique is called \"work stealing\": the"] #[doc = " Rayon runtime uses a fixed pool of worker threads and attempts to"] #[doc = " only execute code in parallel when there are idle CPUs to handle"] #[doc = " it."] #[doc = ""] #[doc = " When `join` is called from outside the thread pool, the calling"] #[doc = " thread will block while the closures execute in the pool. When"] #[doc = " `join` is called within the pool, the calling thread still actively"] #[doc = " participates in the thread pool. It will begin by executing closure"] #[doc = " A (on the current thread). While it is doing that, it will advertise"] #[doc = " closure B as being available for other threads to execute. Once closure A"] #[doc = " has completed, the current thread will try to execute closure B;"] #[doc = " if however closure B has been stolen, then it will look for other work"] #[doc = " while waiting for the thief to fully execute closure B. (This is the"] #[doc = " typical work-stealing strategy)."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " This example uses join to perform a quick-sort (note this is not a"] #[doc = " particularly optimized implementation: if you **actually** want to"] #[doc = " sort for real, you should prefer [the `par_sort` method] offered"] #[doc = " by Rayon)."] #[doc = ""] #[doc = " [the `par_sort` method]: ../rayon/slice/trait.ParallelSliceMut.html#method.par_sort"] #[doc = ""] #[doc = " ```rust"] #[doc = " # use rustc_thread_pool as rayon;"] #[doc = " let mut v = vec![5, 1, 8, 22, 0, 44];"] #[doc = " quick_sort(&mut v);"] #[doc = " assert_eq!(v, vec![0, 1, 5, 8, 22, 44]);"] #[doc = ""] #[doc = " fn quick_sort<T:PartialOrd+Send>(v: &mut [T]) {"] #[doc = "    if v.len() > 1 {"] #[doc = "        let mid = partition(v);"] #[doc = "        let (lo, hi) = v.split_at_mut(mid);"] #[doc = "        rayon::join(|| quick_sort(lo),"] #[doc = "                    || quick_sort(hi));"] #[doc = "    }"] #[doc = " }"] #[doc = ""] #[doc = " // Partition rearranges all items `<=` to the pivot"] #[doc = " // item (arbitrary selected to be the last item in the slice)"] #[doc = " // to the first half of the slice. It then returns the"] #[doc = " // \"dividing point\" where the pivot is placed."] #[doc = " fn partition<T:PartialOrd+Send>(v: &mut [T]) -> usize {"] #[doc = "     let pivot = v.len() - 1;"] #[doc = "     let mut i = 0;"] #[doc = "     for j in 0..pivot {"] #[doc = "         if v[j] <= v[pivot] {"] #[doc = "             v.swap(i, j);"] #[doc = "             i += 1;"] #[doc = "         }"] #[doc = "     }"] #[doc = "     v.swap(i, pivot);"] #[doc = "     i"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " # Warning about blocking I/O"] #[doc = ""] #[doc = " The assumption is that the closures given to `join()` are"] #[doc = " CPU-bound tasks that do not perform I/O or other blocking"] #[doc = " operations. If you do perform I/O, and that I/O should block"] #[doc = " (e.g., waiting for a network request), the overall performance may"] #[doc = " be poor. Moreover, if you cause one closure to be blocked waiting"] #[doc = " on another (for example, using a channel), that could lead to a"] #[doc = " deadlock."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " No matter what happens, both closures will always be executed. If"] #[doc = " a single closure panics, whether it be the first or second"] #[doc = " closure, that panic will be propagated and hence `join()` will"] #[doc = " panic with the same panic value. If both closures panic, `join()`"] #[doc = " will panic with the panic value from the first closure."] pub fn join < A , B , RA , RB > (oper_a : A , oper_b : B) -> (RA , RB) where A : FnOnce () -> RA + Send , B : FnOnce () -> RB + Send , RA : Send , RB : Send , { #[inline] fn call < R > (f : impl FnOnce () -> R) -> impl FnOnce (FnContext) -> R { move | _ | f () } join_context (call (oper_a) , call (oper_b)) }
}

macro_rules! join_context_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function join_context in module {}", module_path!());
    };
}

mkfn!{
    join_context_introspect!();
    #[doc = " Identical to `join`, except that the closures have a parameter"] #[doc = " that provides context for the way the closure has been called,"] #[doc = " especially indicating whether they're executing on a different"] #[doc = " thread than where `join_context` was called. This will occur if"] #[doc = " the second job is stolen by a different thread, or if"] #[doc = " `join_context` was called from outside the thread pool to begin"] #[doc = " with."] pub fn join_context < A , B , RA , RB > (oper_a : A , oper_b : B) -> (RA , RB) where A : FnOnce (FnContext) -> RA + Send , B : FnOnce (FnContext) -> RB + Send , RA : Send , RB : Send , { #[inline] fn call_a < R > (f : impl FnOnce (FnContext) -> R , injected : bool) -> impl FnOnce () -> R { move | | f (FnContext :: new (injected)) } #[inline] fn call_b < R > (f : impl FnOnce (FnContext) -> R) -> impl FnOnce (bool) -> R { move | migrated | f (FnContext :: new (migrated)) } registry :: in_worker (| worker_thread , injected | unsafe { let tlv = tlv :: get () ; let job_b_started = AtomicBool :: new (false) ; let job_b = StackJob :: new (tlv , | migrated | { job_b_started . store (true , Ordering :: Relaxed) ; call_b (oper_b) (migrated) } , SpinLatch :: new (worker_thread) ,) ; let job_b_ref = job_b . as_job_ref () ; let job_b_id = job_b_ref . id () ; worker_thread . push (job_b_ref) ; let status_a = unwind :: halt_unwinding (call_a (oper_a , injected)) ; worker_thread . wait_for_jobs :: < _ , false > (& job_b . latch , | | job_b_started . load (Ordering :: Relaxed) , | job | job . id () == job_b_id , | job | { debug_assert_eq ! (job . id () , job_b_id) ; job_b . run_inline (injected) ; } ,) ; tlv :: set (tlv) ; let result_a = match status_a { Ok (v) => v , Err (err) => unwind :: resume_unwinding (err) , } ; (result_a , job_b . into_result ()) }) }
}